 static List<Vector2> Contour(float w,float h,float rad,bool topOnly=false){var p=new List<Vector2>();for(int q=0;q<4;q++){float r=topOnly&&q>=2?.08f:rad;float cx=q==0||q==3?w/2-r:-w/2+r,cy=q<2?h/2-r:-h/2+r;for(int j=0;j<=8;j++){float a=(q*90+j*90f/8)*Mathf.Deg2Rad;p.Add(new Vector2(cx+r*Mathf.Cos(a),cy+r*Mathf.Sin(a)));}}return p;}
 static Mesh Rounded(float w,float h,float rad,float depth,float border=0,bool topOnly=false){var a=Contour(w,h,rad,topOnly);var v=new List<Vector3>();var tr=new List<int>();Action<Vector3,Vector3,Vector3,Vector3> quad=(p0,p1,p2,p3)=>{int n=v.Count;v.AddRange(new[]{p0,p1,p2,p3});tr.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});};
