 static Mesh Rail(float radius,float y,float height){var v=new List<Vector3>();var tr=new List<int>();for(int i=0;i<=192;i++){v.Add(Polar(radius,i*360f/192,y));v.Add(Polar(radius,i*360f/192,y+height));}for(int i=0;i<192;i++){int n=i*2;tr.AddRange(new[]{n,n+1,n+2,n+1,n+3,n+2});}var m=new Mesh();m.SetVertices(v);m.SetTriangles(tr,0);m.RecalculateNormals();return m;}
