 static void Combine(Transform g,string key){var renderers=g.GetComponentsInChildren<MeshRenderer>(true).ToArray();foreach(var group in renderers.GroupBy(r=>r.sharedMaterial)){var parts=group.Select(r=>new CombineInstance{mesh=r.GetComponent<MeshFilter>().sharedMesh,transform=g.worldToLocalMatrix*r.transform.localToWorldMatrix}).ToArray();var combined=new Mesh{name="Toon batched "+key+" "+group.Key.name,indexFormat=IndexFormat.UInt32};combined.CombineMeshes(parts,true,true);string path=A+"/Batch-"+key+"-"+group.Key.name+".asset";if(File.Exists(path))throw new Exception("Do not overwrite earlier mesh batch");AssetDatabase.CreateAsset(combined,path);MeshObject(g,"Batched "+group.Key.name,combined,group.Key,Vector3.zero);}foreach(var r in renderers)Object.DestroyImmediate(r.gameObject);}
